#[test]
fn bindgen_test_layout_libvlc_media_slave_t() {
    const UNINIT: ::core::mem::MaybeUninit<libvlc_media_slave_t> =
        ::core::mem::MaybeUninit::uninit();
    let ptr = UNINIT.as_ptr();
    assert_eq!(
        ::core::mem::size_of::<libvlc_media_slave_t>(),
        16usize,
        concat!("Size of: ", stringify!(libvlc_media_slave_t))
    );
    assert_eq!(
        ::core::mem::align_of::<libvlc_media_slave_t>(),
        8usize,
        concat!("Alignment of ", stringify!(libvlc_media_slave_t))
    );
    assert_eq!(
        unsafe { ::core::ptr::addr_of!((*ptr).psz_uri) as usize - ptr as usize },
        0usize,
        concat!(
            "Offset of field: ",
            stringify!(libvlc_media_slave_t),
            "::",
            stringify!(psz_uri)
        )
    );
    assert_eq!(
        unsafe { ::core::ptr::addr_of!((*ptr).i_type) as usize - ptr as usize },
        8usize,
        concat!(
            "Offset of field: ",
            stringify!(libvlc_media_slave_t),
            "::",
            stringify!(i_type)
        )
    );
    assert_eq!(
        unsafe { ::core::ptr::addr_of!((*ptr).i_priority) as usize - ptr as usize },
        12usize,
        concat!(
            "Offset of field: ",
            stringify!(libvlc_media_slave_t),
            "::",
            stringify!(i_priority)
        )
    );
}
