#[test]
fn bindgen_test_layout_libvlc_title_description_t() {
    const UNINIT: ::core::mem::MaybeUninit<libvlc_title_description_t> =
        ::core::mem::MaybeUninit::uninit();
    let ptr = UNINIT.as_ptr();
    assert_eq!(
        ::core::mem::size_of::<libvlc_title_description_t>(),
        24usize,
        concat!("Size of: ", stringify!(libvlc_title_description_t))
    );
    assert_eq!(
        ::core::mem::align_of::<libvlc_title_description_t>(),
        8usize,
        concat!("Alignment of ", stringify!(libvlc_title_description_t))
    );
    assert_eq!(
        unsafe { ::core::ptr::addr_of!((*ptr).i_duration) as usize - ptr as usize },
        0usize,
        concat!(
            "Offset of field: ",
            stringify!(libvlc_title_description_t),
            "::",
            stringify!(i_duration)
        )
    );
    assert_eq!(
        unsafe { ::core::ptr::addr_of!((*ptr).psz_name) as usize - ptr as usize },
        8usize,
        concat!(
            "Offset of field: ",
            stringify!(libvlc_title_description_t),
            "::",
            stringify!(psz_name)
        )
    );
    assert_eq!(
        unsafe { ::core::ptr::addr_of!((*ptr).i_flags) as usize - ptr as usize },
        16usize,
        concat!(
            "Offset of field: ",
            stringify!(libvlc_title_description_t),
            "::",
            stringify!(i_flags)
        )
    );
}
